from .store import canonical,digest

ROOT=Path(__file__).resolve().parent
PROFILE_DIR=ROOT/'profiles'
HEX=set('0123456789abcdef')
TOP={'format','system','profile','artifacts','relations','adapters','evidence','decisions','changes','deployment','outcome_evaluations','continuation','closure','assessed_at'}
OPS={'>=':operator.ge,'>':operator.gt,'<=':operator.le,'<':operator.lt,'==':operator.eq}

def _sha(value):return isinstance(value,str) and len(value)==64 and set(value)<=HEX
def _exact(value,keys):return isinstance(value,dict) and set(value)==set(keys)
def deployment_inventory(root):
    root=Path(root)
    return [{'path':str(path.relative_to(root)),'sha256':digest(path.read_bytes()),'size':path.stat().st_size} for path in sorted(x for x in root.rglob('*') if x.is_file() and not x.is_symlink())]

def load_profile(profile,profile_dir=PROFILE_DIR,_seen=None):
    profile_dir=Path(profile_dir);value=json.loads(Path(profile).read_text()) if isinstance(profile,(str,Path)) and Path(profile).exists() else json.loads((profile_dir/(str(profile)+'.json')).read_text()) if isinstance(profile,(str,Path)) else profile
    required={'format','profile_id','version','extends','system_classes','domains','required_edges','controls'}
    if not _exact(value,required) or value['format']!='CLSES-lifecycle-profile/v1':raise ValueError('invalid lifecycle profile shape')
    seen=set() if _seen is None else set(_seen)
    if value['profile_id'] in seen:raise ValueError('cyclic profile extension')
    seen.add(value['profile_id']);domains=[];edges=[];controls=[];lineage=[]
    for parent in value['extends']:
        composed=load_profile(parent,profile_dir,seen);domains+=composed['domains'];edges+=composed['required_edges'];controls+=composed['controls'];lineage+=composed['lineage']
    domains+=value['domains'];edges+=value['required_edges'];controls+=value['controls'];lineage.append({'profile_id':value['profile_id'],'version':value['version']})
    if len(domains)!=len(set(domains)):domains=list(dict.fromkeys(domains))
    control_ids=[x.get('id') for x in controls]
    if len(control_ids)!=len(set(control_ids)):raise ValueError('duplicate control id across composed profiles')
    domain_set=set(domains)
    for control in controls:
        if not _exact(control,{'id','domain','objective','evidence_types','authority_role','max_age_seconds'}) or control['domain'] not in domain_set or not control['evidence_types'] or control['max_age_seconds']<=0:raise ValueError('invalid profile control')
    for edge in edges:
        if not _exact(edge,{'from','to','type'}) or edge['from'] not in domain_set or edge['to'] not in domain_set:raise ValueError('invalid required lifecycle edge')
    return {'profile_id':value['profile_id'],'version':value['version'],'system_classes':value['system_classes'],'domains':domains,'required_edges':edges,'controls':controls,'lineage':lineage}

def signature_valid(bundle,trusted_public_key):
    try:
        with tempfile.TemporaryDirectory() as folder:
            root=Path(folder);data=root/'dossier';sig=root/'signature';data.write_bytes(canonical(bundle['dossier']));sig.write_bytes(base64.b64decode(bundle['signature_base64'],validate=True));return subprocess.run(['openssl','dgst','-sha256','-verify',str(trusted_public_key),'-signature',str(sig),str(data)],capture_output=True).returncode==0
    except (KeyError,ValueError,subprocess.SubprocessError,OSError):return False

