    adapters=d.get('adapters',[]);adapter_index={x.get('id'):x for x in adapters if isinstance(x,dict)};adapter_shape=all(_exact(x,{'format','id','version','digest','capabilities','trust_anchor','execution_boundary'}) and x.get('format')=='CLSES-adapter-manifest/v1' and _sha(x['digest']) and isinstance(x['capabilities'],list) and bool(x['capabilities']) and isinstance(x['trust_anchor'],str) and bool(x['trust_anchor']) and x['execution_boundary'] in ('isolated','external_service','read_only') for x in adapters);checks['adapters']=adapter_shape and len(adapter_index)==len(adapters)
