    decisions=d.get('decisions',[]);decision_index={x.get('id'):x for x in decisions if isinstance(x,dict)};decisions_by_control={};decision_shape=True
    for item in decisions:
        control=controls.get(item.get('control_id'));refs=set(item.get('evidence_refs',[])) if isinstance(item.get('evidence_refs'),list) else set();expected={x['id'] for x in evidence_by_control.get(item.get('control_id'),[])}
        valid=_exact(item,{'id','control_id','target_artifact_id','actor','actor_type','authority_role','outcome','evidence_refs','decided_at','expires_at'}) and control is not None and item.get('target_artifact_id') in artifact_index and artifact_index[item['target_artifact_id']]['domain']==control['domain'] and item.get('actor_type') in ('human','authority_service') and item.get('authority_role')==control['authority_role'] and item.get('outcome')=='approved' and refs==expected and isinstance(item.get('decided_at'),int) and max([x['observed_at'] for x in evidence_by_control.get(item['control_id'],[])],default=now+1)<=item['decided_at']<=d.get('assessed_at',-1) and d.get('assessed_at',now+1)<=now<=item.get('expires_at',-1)
        decision_shape=decision_shape and valid
