def main():
    parser=argparse.ArgumentParser(prog='clses-assure');parser.add_argument('bundle');parser.add_argument('--profile',required=True);parser.add_argument('--deployment-root',required=True);parser.add_argument('--trusted-public-key',required=True);parser.add_argument('--profile-dir',default=str(PROFILE_DIR));args=parser.parse_args();result=assess(json.loads(Path(args.bundle).read_text()),args.profile,args.deployment_root,args.trusted_public_key,profile_dir=args.profile_dir);print(json.dumps(result,indent=2));return 0 if result['valid'] else 1
